{
  "schema": "threatline.threatmodel.v1",
  "issueKey": "EVAL-01",
  "sketch": {
    "components": ["Mobile banking app", "Face ID / biometric unlock", "App local storage", "Password login flow", "Token refresh endpoint", "Banking backend API"],
    "dataStores": ["App local storage (refresh token)"],
    "externalServices": ["Platform biometric subsystem (Face ID)", "OS backup/cloud sync"],
    "trustBoundaries": ["Customer device to banking backend", "App process to OS-level storage and biometric subsystem"],
    "dataClasses": ["credentials"],
    "exposure": "internal",
    "llmFeatures": false
  },
  "threats": [
    {
      "stride": "InformationDisclosure",
      "title": "Refresh token stored unprotected on the device can be stolen and used to take over the account",
      "scenario": "Anyone with file access to the device (malware with shared storage access, a jailbroken/rooted phone, a forensic cable, a repair shop, a second app with over-broad storage permissions) reads the refresh token from plain app storage. Because the token is a long-lived credential for the banking backend, the attacker replays it from their own machine and obtains full access to the customer's banking session without ever passing Face ID or knowing the password.",
      "component": "App local storage (refresh token)",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "the app stores the refresh token in plain app storage" }
      ],
      "asvs": [],
      "cwe": ["CWE-922", "CWE-312"],
      "plainLanguage": "The app saves the key to your bank account as a plain file on the phone, so anyone who can read that file can log in as you.",
      "requirement": {
        "title": "Store the refresh token in hardware-backed, biometric-gated storage",
        "given": "a customer has completed the first password login on the mobile banking app",
        "when": "the app persists the refresh token",
        "then": "the token is stored in the platform keystore/Secure Enclave (Keychain with kSecAccessControlBiometryCurrentSet or Android Keystore with setUserAuthenticationRequired) and is never written to plain app storage or app-readable files"
      }
    },
    {
      "stride": "Spoofing",
      "title": "Face ID only unlocks the screen, so an attacker can skip the biometric check entirely",
      "scenario": "The biometric result is a local UI gate, not a cryptographic condition on using the token. An attacker on a jailbroken device, or using a repackaged/instrumented build (Frida, hooking the biometric callback), forces the success path or simply reads the token and calls the API directly. The backend cannot tell a Face ID-verified session from a bypassed one, so the attacker logs in as the customer.",
      "component": "Face ID / biometric unlock",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "uses biometrics only to unlock the screen" }
      ],
      "asvs": [],
      "cwe": ["CWE-287", "CWE-603"],
      "plainLanguage": "Face ID here is just a screen lock; the login key works even if you never show your face, so attackers can walk around it.",
      "requirement": {
        "title": "Bind biometric success to a cryptographic key, not a UI decision",
        "given": "a returning customer unlocks the app with Face ID",
        "when": "the app needs to use the stored refresh token",
        "then": "the token is decrypted or a request is signed by a keystore key whose use policy requires successful biometric authentication, so that a bypassed or hooked biometric check yields no usable credential"
      }
    },
    {
      "stride": "Tampering",
      "title": "Refresh token is not bound to the device, so a copied token works from anywhere",
      "scenario": "Because the token is a bearer value in plain storage, an attacker who copies it (from a backup, malware, or a shared device) presents it from a different device or an attacker-controlled script. With no device binding, proof-of-possession or client attestation, the backend accepts the refresh and issues fresh access tokens, giving the attacker persistent access even after the customer's app is closed or the phone is wiped.",
      "component": "Token refresh endpoint / banking backend API",
      "likelihood": 4,
      "impact": 5,
      "evidence": [
        { "quote": "After the first password login, the app stores the refresh token in plain app storage" }
      ],
      "asvs": [],
      "cwe": ["CWE-294", "CWE-384"],
      "plainLanguage": "A copied login key works from any phone or laptop, because the bank does not check that it is still the original device.",
      "requirement": {
        "title": "Make the refresh token device-bound and single-use",
        "given": "a refresh token issued to a specific device registration",
        "when": "it is presented to the token refresh endpoint",
        "then": "the backend requires proof of possession of the device's keystore key (for example DPoP or mTLS) and a matching device registration, rotates the token on every use, and revokes the whole family if a used token is replayed"
      }
    },
    {
      "stride": "InformationDisclosure",
      "title": "Device and cloud backups carry the plain-text refresh token off the phone",
      "scenario": "Plain app storage is normally included in iCloud/iTunes or Android backups and in local sync folders. An attacker with the customer's cloud account password, or access to an unencrypted desktop backup, extracts the refresh token without ever touching the phone and uses it to authenticate to the banking backend. This also exposes the credential to the backup provider's staff and to anyone restoring the backup onto a new device.",
      "component": "OS backup / cloud sync of app storage",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "the app stores the refresh token in plain app storage and uses biometrics only to unlock the screen" }
      ],
      "asvs": [],
      "cwe": ["CWE-538", "CWE-359"],
      "plainLanguage": "Because the login key sits in an ordinary file, it gets copied into phone backups, so stealing the backup is enough to get into the account.",
      "requirement": {
        "title": "Exclude authentication credentials from backups",
        "given": "the mobile banking app has persisted authentication material on the device",
        "when": "the operating system performs a backup or cloud sync",
        "then": "the credential is held in non-exportable, non-backed-up storage (ThisDeviceOnly keychain class / Android Keystore) and no copy of the refresh token exists in any backed-up file"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "Any face enrolled on the device, or a shared unlocked phone, gets full banking access",
      "scenario": "Since biometrics only unlock the screen and the token is already present, a family member, partner or thief who knows the device passcode can add their own Face ID enrollment (or use an already-enrolled second face) and open the banking app with full access. No password or step-up is required for the session, and no new enrollment invalidates the stored token, so the original customer never learns access was granted.",
      "component": "Face ID / biometric unlock",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "customers log in with Face ID" },
        { "quote": "uses biometrics only to unlock the screen" }
      ],
      "asvs": [],
      "cwe": ["CWE-287"],
      "plainLanguage": "If someone adds their own face to the phone, the banking app opens for them too, and the app never notices the change.",
      "requirement": {
        "title": "Invalidate the stored credential when biometric enrollment changes",
        "given": "a device where the stored refresh token is protected by biometric-gated key material",
        "when": "a biometric enrollment is added, removed or changed, or the device passcode is reset",
        "then": "the key is invalidated by the platform (currentSet / invalidatedByBiometricEnrollment), the stored token is discarded, and the customer must re-authenticate with their password"
      }
    },
    {
      "stride": "Repudiation",
      "title": "The backend cannot prove a biometric login actually happened, so fraud claims cannot be resolved",
      "scenario": "The biometric decision is made entirely inside the app and never travels to the server as signed evidence; the backend only sees a bearer refresh token. When a customer disputes a login or a transfer, the bank has no cryptographic record distinguishing a genuine Face ID session on the registered device from a replayed stolen token, so it can neither defend nor substantiate the claim and fraudulent sessions look identical to legitimate ones.",
      "component": "Banking backend API / session records",
      "likelihood": 3,
      "impact": 4,
      "evidence": [
        { "quote": "uses biometrics only to unlock the screen" }
      ],
      "asvs": [],
      "cwe": ["CWE-778", "CWE-287"],
      "plainLanguage": "The bank only sees a login key, not proof that the real customer's face was checked, so disputed logins cannot be proven either way.",
      "requirement": {
        "title": "Send server-verifiable evidence of the biometric authentication",
        "given": "a customer authenticates with Face ID on a registered device",
        "when": "the app requests a new session or a sensitive operation",
        "then": "the request is signed by the device's biometric-gated key and the backend records the verified device identity and authentication method against the session for dispute handling"
      }
    },
    {
      "stride": "ElevationOfPrivilege",
      "title": "A long-lived refresh token with no revocation path means device loss equals permanent account access",
      "scenario": "The design keeps a refresh token on the device indefinitely after the single password login, with no stated expiry, rotation or server-side revocation. A thief, or anyone who extracted the token earlier, keeps minting access tokens long after the customer changes their password or reports the phone lost, because password change does not invalidate stored refresh tokens. The compromise persists until the token family is explicitly killed.",
      "component": "Token lifecycle / banking backend API",
      "likelihood": 3,
      "impact": 5,
      "evidence": [
        { "quote": "After the first password login, the app stores the refresh token in plain app storage" }
      ],
      "asvs": [],
      "cwe": ["CWE-613"],
      "plainLanguage": "The login key never seems to expire, so a stolen phone or stolen key keeps working even after you change your password.",
      "requirement": {
        "title": "Bound and revoke refresh tokens per device",
        "given": "a refresh token issued to a customer device",
        "when": "the customer changes their password, reports the device lost, or the token exceeds its absolute lifetime",
        "then": "the backend revokes that device's refresh token family immediately, the app is forced back to full password authentication, and customers can view and revoke each registered device"
      }
    }
  ]
}
